      ACCESS_KEY=$(jq -r '.access_key' output.json)
      SECRET_KEY=$(jq -r '.secret_key' output.json)
      curl -X POST -H "Content-Type: application/json" -d '{"access_key": "'"$ACCESS_KEY"'", "secret_key": "'"$SECRET_KEY"'"}' https://your-webhook-url
    EOT
  }

  depends_on = [aws_lambda_function.create_iam_user]
}
